-- FZ ERP production baseline schema (PostgreSQL 14+)
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS roles(id SERIAL PRIMARY KEY,name VARCHAR(50) UNIQUE NOT NULL,description TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,name VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS user_roles(user_id INT REFERENCES users(id) ON DELETE CASCADE,role_id INT REFERENCES roles(id) ON DELETE CASCADE,PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS permissions(id SERIAL PRIMARY KEY,resource VARCHAR(80) NOT NULL,action VARCHAR(40) NOT NULL,UNIQUE(resource,action));
CREATE TABLE IF NOT EXISTS role_permissions(id SERIAL PRIMARY KEY,role_id INT REFERENCES roles(id) ON DELETE CASCADE,resource VARCHAR(80) NOT NULL,action VARCHAR(40) NOT NULL,UNIQUE(role_id,resource,action));
CREATE TABLE IF NOT EXISTS customers(id SERIAL PRIMARY KEY,customer_code VARCHAR(50) UNIQUE,name VARCHAR(255) NOT NULL,email VARCHAR(255),phone VARCHAR(50),city VARCHAR(100),country VARCHAR(100),vat_number VARCHAR(100),website TEXT,default_currency CHAR(3) DEFAULT 'EUR',credit_limit NUMERIC(15,2),status VARCHAR(30) DEFAULT 'ACTIVE',notes TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS customer_contacts(id SERIAL PRIMARY KEY,customer_id INT REFERENCES customers(id) ON DELETE CASCADE,name VARCHAR(255) NOT NULL,email VARCHAR(255),phone VARCHAR(50),position VARCHAR(100),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers(id SERIAL PRIMARY KEY,name VARCHAR(255) UNIQUE NOT NULL,email VARCHAR(255),phone VARCHAR(50),city VARCHAR(100),country VARCHAR(100),currency CHAR(3) DEFAULT 'EUR',payment_terms TEXT,status VARCHAR(30) DEFAULT 'ACTIVE',notes TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,product_name_en VARCHAR(255),product_name_tr VARCHAR(255),sku VARCHAR(100) UNIQUE NOT NULL,description TEXT,hs_code VARCHAR(30),product_family VARCHAR(100),category VARCHAR(100),supplier_id INT REFERENCES suppliers(id),unit_price NUMERIC(15,2) DEFAULT 0,purchase_price NUMERIC(15,2) DEFAULT 0,sale_price NUMERIC(15,2) DEFAULT 0,currency CHAR(3) DEFAULT 'EUR',margin_percent NUMERIC(8,2),drawing_file_url TEXT,status VARCHAR(30) DEFAULT 'ACTIVE',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS product_price_history(id BIGSERIAL PRIMARY KEY,product_id INT REFERENCES products(id),purchase_price NUMERIC(15,2),sale_price NUMERIC(15,2),margin_percent NUMERIC(8,2),currency CHAR(3),valid_from TIMESTAMPTZ DEFAULT now(),created_by INT REFERENCES users(id));
CREATE SEQUENCE IF NOT EXISTS order_number_seq START 1;CREATE SEQUENCE IF NOT EXISTS offer_number_seq START 1;CREATE SEQUENCE IF NOT EXISTS invoice_number_seq START 1;CREATE SEQUENCE IF NOT EXISTS shipment_number_seq START 1;
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,order_number VARCHAR(100) UNIQUE NOT NULL,customer_id INT NOT NULL REFERENCES customers(id),customer_order_number VARCHAR(100),customer_order_date TIMESTAMPTZ,requested_delivery_date TIMESTAMPTZ,status VARCHAR(40) DEFAULT 'draft',total_amount NUMERIC(15,2) DEFAULT 0,currency CHAR(3) DEFAULT 'EUR',created_by INT REFERENCES users(id),notes TEXT,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS order_items(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,product_id INT NOT NULL REFERENCES products(id),quantity NUMERIC(15,3) NOT NULL CHECK(quantity>0),unit_purchase_price NUMERIC(15,2) DEFAULT 0,unit_sale_price NUMERIC(15,2) NOT NULL,margin_percent NUMERIC(8,2),currency CHAR(3) DEFAULT 'EUR',total_sale_price NUMERIC(15,2) NOT NULL,options_snapshot JSONB DEFAULT '{}',supplier_invoice_number VARCHAR(100),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS order_status_history(id BIGSERIAL PRIMARY KEY,order_id INT REFERENCES orders(id),from_status VARCHAR(40),to_status VARCHAR(40) NOT NULL,changed_by INT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS order_costs(id SERIAL PRIMARY KEY,order_id INT UNIQUE REFERENCES orders(id),internal_transport_cost NUMERIC(15,2) DEFAULT 0,external_transport_cost NUMERIC(15,2) DEFAULT 0,customs_cost NUMERIC(15,2) DEFAULT 0,other_cost NUMERIC(15,2) DEFAULT 0,total_cost NUMERIC(15,2) DEFAULT 0,cost_currency CHAR(3) DEFAULT 'EUR',exchange_rate_snapshot NUMERIC(15,6),profit NUMERIC(15,2),margin_percent NUMERIC(8,2));
CREATE TABLE IF NOT EXISTS price_offers(id SERIAL PRIMARY KEY,offer_number VARCHAR(100) UNIQUE NOT NULL,customer_id INT REFERENCES customers(id),status VARCHAR(30) DEFAULT 'DRAFT',total_amount NUMERIC(15,2) DEFAULT 0,currency CHAR(3) DEFAULT 'EUR',valid_until TIMESTAMPTZ,created_by INT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS price_offer_items(id SERIAL PRIMARY KEY,price_offer_id INT REFERENCES price_offers(id) ON DELETE CASCADE,product_id INT REFERENCES products(id),quantity NUMERIC(15,3) NOT NULL,unit_purchase_price NUMERIC(15,2) DEFAULT 0,unit_price NUMERIC(15,2) NOT NULL,margin_percent NUMERIC(8,2),total_price NUMERIC(15,2) NOT NULL,options_snapshot JSONB DEFAULT '{}');
CREATE TABLE IF NOT EXISTS invoices(id SERIAL PRIMARY KEY,invoice_number VARCHAR(100) UNIQUE NOT NULL,external_invoice_number VARCHAR(100) UNIQUE,order_id INT REFERENCES orders(id),customer_id INT NOT NULL REFERENCES customers(id),status VARCHAR(30) DEFAULT 'DRAFT',total_amount NUMERIC(15,2) NOT NULL,currency CHAR(3) DEFAULT 'EUR',exchange_rate_snapshot NUMERIC(15,6),due_date TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS supplier_invoices(id SERIAL PRIMARY KEY,supplier_id INT REFERENCES suppliers(id),order_id INT REFERENCES orders(id),invoice_number VARCHAR(100) NOT NULL,amount NUMERIC(15,2) NOT NULL,currency CHAR(3) DEFAULT 'EUR',exchange_rate_snapshot NUMERIC(15,6),invoice_date TIMESTAMPTZ,due_date TIMESTAMPTZ,status VARCHAR(30) DEFAULT 'UNPAID',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ,UNIQUE(supplier_id,invoice_number));
CREATE TABLE IF NOT EXISTS payments(id SERIAL PRIMARY KEY,invoice_id INT REFERENCES invoices(id),amount NUMERIC(15,2) NOT NULL CHECK(amount>0),payment_date TIMESTAMPTZ NOT NULL,payment_method VARCHAR(40),currency CHAR(3) DEFAULT 'EUR',exchange_rate_to_eur NUMERIC(15,6),reference_number VARCHAR(100),status VARCHAR(30) DEFAULT 'RECORDED',notes TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier_payments(id SERIAL PRIMARY KEY,supplier_invoice_id INT REFERENCES supplier_invoices(id),amount NUMERIC(15,2) NOT NULL,currency CHAR(3) DEFAULT 'EUR',exchange_rate_to_eur NUMERIC(15,6),payment_date TIMESTAMPTZ NOT NULL,payment_method VARCHAR(40),reference_number VARCHAR(100),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS shipments(id SERIAL PRIMARY KEY,shipment_number VARCHAR(100) UNIQUE NOT NULL,order_id INT NOT NULL REFERENCES orders(id),status VARCHAR(30) DEFAULT 'PENDING',shipment_date TIMESTAMPTZ,expected_delivery TIMESTAMPTZ,carrier VARCHAR(255),tracking_number VARCHAR(255),incoterm_code VARCHAR(10),created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS shipment_items(id SERIAL PRIMARY KEY,shipment_id INT REFERENCES shipments(id) ON DELETE CASCADE,order_item_id INT REFERENCES order_items(id),quantity NUMERIC(15,3) NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS packing_lists(id SERIAL PRIMARY KEY,shipment_id INT UNIQUE REFERENCES shipments(id),gross_weight NUMERIC(15,3),net_weight NUMERIC(15,3),pallet_count INT,package_count INT,notes TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS loading_instructions(id SERIAL PRIMARY KEY,shipment_id INT REFERENCES shipments(id),instruction_text TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS exchange_rates(id BIGSERIAL PRIMARY KEY,from_currency CHAR(3) NOT NULL,to_currency CHAR(3) NOT NULL,rate NUMERIC(18,8) NOT NULL,rate_date DATE NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(from_currency,to_currency,rate_date));
CREATE TABLE IF NOT EXISTS claims(id SERIAL PRIMARY KEY,invoice_id INT REFERENCES invoices(id),order_id INT REFERENCES orders(id),description TEXT NOT NULL,amount NUMERIC(15,2) NOT NULL,status VARCHAR(30) DEFAULT 'OPEN',created_by INT REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS claim_approvals(id SERIAL PRIMARY KEY,claim_id INT REFERENCES claims(id),amount NUMERIC(15,2) NOT NULL,approved_by INT REFERENCES users(id),approved_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS credit_memos(id SERIAL PRIMARY KEY,claim_id INT REFERENCES claims(id),amount NUMERIC(15,2) NOT NULL,approved_by INT REFERENCES users(id),approved_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,user_id INT REFERENCES users(id),action VARCHAR(100) NOT NULL,resource VARCHAR(100),resource_id INT,changes JSONB,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS email_logs(id BIGSERIAL PRIMARY KEY,recipient VARCHAR(255) NOT NULL,subject VARCHAR(255),template VARCHAR(100),status VARCHAR(30),error_message TEXT,sent_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_orders_customer ON orders(customer_id);CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);CREATE INDEX IF NOT EXISTS idx_invoices_customer ON invoices(customer_id);CREATE INDEX IF NOT EXISTS idx_payments_invoice ON payments(invoice_id);CREATE INDEX IF NOT EXISTS idx_shipments_order ON shipments(order_id);CREATE INDEX IF NOT EXISTS idx_rates_date ON exchange_rates(rate_date);
INSERT INTO roles(name,description) VALUES('Admin','Full access'),('Sales','Sales operations'),('Accountant','Finance'),('Warehouse','Logistics'),('Viewer','Read only') ON CONFLICT(name) DO NOTHING;
INSERT INTO permissions(resource,action) VALUES('customers','read'),('customers','create'),('customers','update'),('customers','delete'),('suppliers','read'),('suppliers','create'),('suppliers','update'),('suppliers','delete'),('products','read'),('products','create'),('products','update'),('products','delete'),('orders','read'),('orders','create'),('orders','update'),('orders','delete'),('offers','read'),('offers','create'),('offers','update'),('offers','delete'),('invoices','read'),('invoices','create'),('invoices','update'),('invoices','delete'),('payments','read'),('payments','create'),('shipments','read'),('shipments','create'),('shipments','update'),('claims','read'),('claims','create'),('claims','update'),('reports','read'),('currencies','read'),('currencies','sync') ON CONFLICT(resource,action) DO NOTHING;
INSERT INTO role_permissions(role_id,resource,action) SELECT r.id,p.resource,p.action FROM roles r CROSS JOIN permissions p WHERE r.name='Admin' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,resource,action) SELECT r.id,p.resource,p.action FROM roles r JOIN permissions p ON p.resource IN('customers','products','offers','orders') WHERE r.name='Sales' AND p.action IN('read','create','update') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,resource,action) SELECT r.id,p.resource,p.action FROM roles r JOIN permissions p ON p.resource IN('invoices','payments','reports','currencies') WHERE r.name='Accountant' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,resource,action) SELECT r.id,p.resource,p.action FROM roles r JOIN permissions p ON p.resource IN('shipments','orders','products') WHERE r.name='Warehouse' AND p.action IN('read','create','update') ON CONFLICT DO NOTHING;
